function requestsPage(){$('#main').innerHTML=`<div class="page-intro"><p>مركز الطلبات وموافقات المدير المباشر</p><button class="primary" id="newReq">＋ ${me.role==='manager'?'انتداب موظف':'طلب جديد'}</button></div><div class="panel">${requestTable(requests.filter(r=>r.type!=='hr_contact'))}</div>`;$('#newReq').onclick=()=>newRequest()}
function newRequest(contact=false){
 const allowed=contact?['hr_contact']:me.role==='manager'?['delegation']:Object.keys(types).filter(x=>!['delegation','hr_contact'].includes(x));
 const es=contact&&me.role!=='admin'?employees.filter(e=>e.id===me.employee_id):me.role==='admin'?employees.filter(e=>!e.archived):me.role==='manager'?employees.filter(e=>!e.archived&&canSupervise(e)&&e.id!==me.employee_id):employees.filter(e=>e.id===me.employee_id);
 if(!es.length)return notify('لا يوجد موظفون متاحون',true);
 const fields=[...requestSpecificFields(),dropdown('employee_id','الموظف',es.map(e=>[e.id,e.name])),dropdown('type','نوع الطلب',allowed.map(k=>[k,types[k]])),field('start_date','من تاريخ','date'),field('end_date','إلى تاريخ','date'),field('amount','مبلغ السلفة (ريال)','number',0,'min="0" step="0.01"'),field('installment','القسط الشهري (ريال)','number',0,'min="0" step="0.01"'),`<label class="full">ملاحظات<textarea name="notes"></textarea></label>`,`<label class="full">المرفقات (PNG / JPG / PDF)<input type="file" name="attachments" accept=".png,.jpg,.jpeg,.pdf" multiple><small>حتى 3 ملفات، بحد أقصى 2 ميجابايت لكل ملف</small></label>`];
 openModal(contact?'تواصل مع الموارد البشرية':'طلب جديد',formwrap(fields,'إرسال الطلب'),async v=>{v.attachments=await requestAttachments(form);if(v.type!=='advance'){delete v.amount;delete v.installment}const x=await api('/requests',v);notify('تم تسجيل '+x.number)});
 const form=$('#modalBody form'),type=form.querySelector('[name=type]'),employee=form.querySelector('[name=employee_id]');
 const preview=document.createElement('div');preview.className='advance-preview';form.querySelector('[name=installment]').closest('label').after(preview);
 let previewVersion=0;
 async function updatePreview(){const version=++previewVersion,isAdvance=type.value==='advance';preview.hidden=!isAdvance;
  for(const key of ['amount','installment']){const input=form.querySelector(`[name=${key}]`);input.closest('label').hidden=!isAdvance;input.disabled=!isAdvance;input.required=isAdvance}
  updateRequestFields(form,type.value);
  const needDates=['annual_leave','sick_leave','unpaid_leave','permission','delegation'].includes(type.value);
  for(const key of ['start_date','end_date'])form.querySelector(`[name=${key}]`).required=needDates||(key==='start_date'&&type.value==='punch_fix');
  if(type.value==='annual_leave'){preview.hidden=false;preview.textContent='أدخل التواريخ لمعاينة الرصيد';const a=form.querySelector('[name=start_date]').value,b=form.querySelector('[name=end_date]').value;if(a&&b){try{const out=await api('/leave/preview',{employee_id:employee.value,start_date:dateISO(a),end_date:dateISO(b),last_day_fraction:form.querySelector('[name=last_day_fraction]')?.value||1});if(version===previewVersion)preview.innerHTML=`أيام العمل: ${fmt(out.days)}<br>الرصيد الشهري الحالي: ${fmt(out.monthly_available)} · المتوقع بعد الاعتماد شهريًا: ${fmt(out.monthly_after_approval)}<br>الرصيد الإجمالي الحالي: ${fmt(out.available)} · المتوقع بعد الاعتماد إجماليًا: ${fmt(out.after_approval)}`}catch(e){if(version===previewVersion)preview.textContent=e.message}}return}if(!isAdvance)return;preview.textContent='جارٍ حساب الاستحقاق...';try{const info=await api('/advance/preview?employee_id='+encodeURIComponent(employee.value));if(version!==previewVersion)return;preview.innerHTML=`<strong>حاسبة استحقاق السلفة</strong><p>الراتب الإجمالي: ${fmt(info.gross_salary)} ريال · الحد الشهري (35%): ${fmt(info.max_monthly_installment)} ريال</p><p>الأشهر المتبقية: ${info.remaining_months} · الحد الأقصى: ${fmt(info.max_advance)} ريال</p>`}catch(err){if(version===previewVersion)preview.textContent=err.message}}
 type.onchange=updatePreview;employee.onchange=updatePreview;form.querySelectorAll('[data-date],[name=last_day_fraction]').forEach(x=>x.addEventListener('change',updatePreview));updatePreview();
}
window.requestDetail=async id=>{
 let r;try{r=await api('/requests/'+id)}catch(e){notify(e.message,true);return}const cached=requests.findIndex(x=>x.id===id);if(cached>=0)requests[cached]=r;const e=employees.find(e=>e.id===r.employee_id);
 let html=`<div class="info"><b>EH-${String(r.id).padStart(6,'0')} · ${esc(types[r.type])}</b><br>الموظف: ${esc(r.employee_name||e?.name)}<br>الحالة: ${esc(statuses[r.status])}<br>من ${esc(dateDisplay(r.start_date)||'—')} إلى ${esc(dateDisplay(r.end_date)||'—')}<br>عدد أيام العمل: ${fmt(r.days)}${r.type==='advance'?`<br>مبلغ السلفة: ${fmt(r.amount)} ريال · القسط الشهري: ${fmt(r.installment)} ريال`:''}<br>الملاحظات: <span class="preserve-lines" data-i18n-ignore>${esc(r.notes)}</span></div>`;
 html+=requestMetadata(r);
 html+=`<section><h4>المرفقات</h4>${(r.attachments||[]).map(a=>`<p><a href="/api/attachments/${a.id}" download>${esc(a.name)}</a> (${fmt(a.size/1024)} كيلوبايت)</p>`).join('')||'<p>لا توجد مرفقات</p>'}</section>`;
 html+=`<section><h4>سجل القرارات</h4>${(r.decisions||[]).map(d=>`<p>${esc(statuses[d.status]||d.status)} · ${esc(d.username)} · <bdi>${esc(dateDisplay(d.decided_at))}</bdi><br><span class="preserve-lines" data-i18n-ignore>${esc(d.note)}</span></p>`).join('')||(r.decision_note?`<p>قرار سابق: ${esc(r.decision_note)} (بيانات صاحب القرار غير متاحة في السجل القديم)</p>`:'<p>لم يصدر قرار بعد</p>')}</section>`;
 let buttons=[];
 if(['new','review'].includes(r.status)){
  if(r.type!=='delegation'&&(r.type!=='investigation'||me.role==='admin')&&me.employee_id!==r.employee_id&&(me.role==='admin'||(me.role==='manager'&&canSupervise(e)&&r.approval_mode!=='admin_only')))buttons=[['review','تحت المراجعة'],['approved','موافقة'],['rejected','رفض']];
  if(me.role==='employee'&&r.type==='delegation')buttons=[['accepted','قبول الانتداب'],['declined','رفض الانتداب']];
 }
 if(me.role==='admin'&&['new','review'].includes(r.status))buttons.push(['closed','إغلاق دون اعتماد'],['cancelled','إلغاء الطلب']);
 if(me.role==='admin'&&r.status==='approved')buttons=[['cancelled','إلغاء المعتمد']];
 html+=`<div class="actions">${buttons.map(([v,t])=>`<button class="${['rejected','declined'].includes(v)?'danger':'secondary'}" data-status="${v}">${t}</button>`).join('')}</div>`;
 openModal('تفاصيل الطلب',html);bindRequestExtras(r);if(r.created_by===me.id&&['new','review'].includes(r.status)){const button=document.createElement('button');button.className='ghost';button.textContent='سحب طلبي';button.onclick=async()=>{try{await api('/requests/'+id,{status:'withdrawn'});$('#modal').close();await refresh();await render()}catch(e){notify(e.message,true)}};$('#modalBody').append(button)}
 document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{try{const action=b.dataset.status,rejection=['rejected','declined'].includes(action),files=await requestAttachments($('#modalBody'));const note=await askText('تأكيد قرار الطلب',rejection?'سبب الرفض (إلزامي)':'ملاحظات القرار',rejection);if(note===null)return requestDetail(id);await api('/requests/'+id,{status:action,note,attachments:files});await refresh();await render();notify('تم تحديث الطلب')}catch(e){notify(e.message,true)}});
};
async function leavePage(){const es=employees.filter(e=>!e.archived);if(!es.length)return $('#main').innerHTML='<div class="empty">لا يوجد موظفون</div>';const eid=selectedEmployee&&es.some(e=>e.id===selectedEmployee)?selectedEmployee:es[0].id;const balances=await api('/leave/'+eid);$('#main').innerHTML=`<div class="page-intro"><p>عرض الرصيد المتراكم ورصيد العقد والإجمالي المتاح</p></div><div class="filterbar">${dropdown('leaveEmployee','الموظف',es.map(e=>[e.id,e.name]),eid)}</div><div class="balance">${stat('الرصيد المتراكم',balances.carryover)}${stat('المستحق من العقد',balances.accrued)}${stat('الرصيد الشهري',balances.monthly_allowance)}${stat('الإجمالي المتاح',balances.available)}</div><div class="panel"><h3>تفاصيل احتساب الرصيد</h3><p>الاستحقاق السنوي: <b>${fmt(balances.annual_entitlement)} يومًا</b>، الأشهر المكتملة داخل العقد: <b>${fmt(balances.elapsed_months)}</b>، الأيام المعتمدة المخصومة: <b>${fmt(balances.approved_used)}</b>.</p><p class="muted">يكتسب الرصيد عن الأشهر المكتملة حتى نهاية العقد، ويُرحّل المتبقي عند تسجيل تجديد العقد. تُستبعد أيام الراحة والعطلات المعرفة للشركة.</p><p>خصم الغياب المعتمد: ${fmt(balances.absence_used)} يوم · رصيد تمت تسويته: ${fmt(balances.settled_days)} يوم</p>${simpleTable(balances.monthly_history)}${me.role==='admin'?`<button id="renewContract" class="secondary">تجديد العقد وترحيل الرصيد</button>`:''}</div>`;if($('#renewContract'))$('#renewContract').onclick=()=>renewContract(eid);$('[name=leaveEmployee]').onchange=e=>{selectedEmployee=+e.target.value;leavePage()}}
async function attendancePage(){
 const isEmployee=me.role==='employee';const es=employees.filter(e=>!e.archived);const id=isEmployee?me.employee_id:(selectedEmployee&&es.some(e=>e.id===selectedEmployee)?selectedEmployee:es[0]?.id);
 if(!id)return $('#main').innerHTML='<div class="empty">لا يوجد موظفون</div>';
 const rows=await api('/attendance?employee_id='+id);
 $('#main').innerHTML=`<div class="page-intro"><div><h3>الحضور والانصراف</h3><p>${isEmployee?'سجّل حضورك أو انصرافك وأنت داخل نطاق موقع الشركة المحدد.':'سجل البصمات الجغرافية حسب صلاحياتك.'}</p></div>${isEmployee?`<button id="geoPunch" class="primary">${rows.some(r=>r.day===currentDate()&&r.check_in&&!r.check_out)?'تأكيد تسجيل الانصراف':'تسجيل الحضور'}</button>`:''}</div>${isEmployee?'<div class="panel info">اسمح للمتصفح باستخدام الموقع. يلزم أن تكون دقة الموقع 100 متر أو أفضل وأن تكون داخل نطاق الشركة.</div>':`<div class="filterbar">${dropdown('attEmployee','الموظف',es.map(e=>[e.id,e.name]),id)}${field('from','من تاريخ','date')}${field('to','إلى تاريخ','date')}<button id="filterAtt" class="secondary">بحث</button></div>`}<div class="panel" id="attendanceRows">${attendanceTable(rows)}</div>`;
 addAttendanceFilters(id);
 if(isEmployee){$('#geoPunch').onclick=()=>{if(!navigator.geolocation)return notify('المتصفح لا يدعم تحديد الموقع',true);const b=$('#geoPunch');if(!confirm(tr('تأكيد إجراء البصمة: ')+b.textContent))return;b.disabled=true;b.textContent='جارٍ تحديد الموقع...';navigator.geolocation.getCurrentPosition(async pos=>{try{const out=await api('/attendance',{action:rows.some(r=>r.check_in&&!r.check_out)?'check_out':'check_in',latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy});notify(out.message+' · المسافة '+out.distance_m+' متر');await render()}catch(err){notify(err.message,true);b.disabled=false;b.textContent='تحديد موقعي وتسجيل البصمة'}},err=>{notify(err.code===1?'اسمح للموقع من إعدادات المتصفح ثم حاول مجددًا':'تعذر تحديد موقعك. فعّل GPS وحاول مجددًا',true);b.disabled=false;b.textContent='تحديد موقعي وتسجيل البصمة'},{enableHighAccuracy:true,timeout:15000,maximumAge:0})}}
 else{$('[name=attEmployee]').onchange=e=>{selectedEmployee=+e.target.value;attendancePage()};$('#filterAtt').onclick=async()=>{try{const qs=new URLSearchParams({employee_id:id,from:dateISO($('[name=from]').value),to:dateISO($('[name=to]').value)});$('#attendanceRows').innerHTML=attendanceTable(await api('/attendance?'+qs))}catch(e){notify(e.message,true)}}}
}
function attendanceTable(rows){return rows.length?`<div class="table-wrap"><table><tr><th>اليوم</th><th>الحضور</th><th>الانصراف</th><th>المصدر</th></tr>${rows.map(x=>`<tr><td>${esc(dateDisplay(x.day))}</td><td>${esc(x.check_in||'—')}</td><td>${esc(x.check_out||'—')}</td><td>${esc(x.source)}</td></tr>`).join('')}</table></div>`:'<div class="empty">لا توجد بصمات لهذه الفترة</div>'}

async function archivePage(){const archivedCompanies=companies.filter(c=>c.archived),archivedEmployees=employees.filter(e=>e.archived);let history=[];try{history=await api('/archive/history')}catch(err){notify(err.message,true)}$('#main').innerHTML=`<div class="panel"><h3>الشركات المؤرشفة</h3>${archivedCompanies.map(c=>`<div class="meta">${esc(c.name)} <button class="secondary small" onclick="archiveItem('company',${c.id},false)">استرجاع</button></div>`).join('')||'<div class="empty">لا توجد شركات مؤرشفة</div>'}</div><div class="panel"><h3>الموظفون المؤرشفون</h3>${archivedEmployees.map(e=>`<div class="meta">${esc(e.name)} <button class="secondary small" onclick="archiveItem('employee',${e.id},false)">استرجاع</button></div>`).join('')||'<div class="empty">لا يوجد موظفون مؤرشفون</div>'}</div><div class="panel"><h3>سجل الأرشفة والاسترجاع</h3><div class="table-wrap"><table><thead><tr><th>الوقت</th><th>المستخدم</th><th>الإجراء</th><th>النوع</th><th>رقم السجل</th></tr></thead><tbody>${history.map(x=>`<tr><td>${esc(dateDisplay(x.timestamp))}</td><td>${esc(x.username)} · ${esc(x.display_name)}</td><td>${x.action==='archive'?'أرشفة':'استرجاع'}</td><td>${x.entity==='company'?'شركة':'موظف'}</td><td>${esc(x.entity_id)}</td></tr>`).join('')}</tbody></table></div>${history.length?'':'<div class="empty">لا توجد عمليات مسجلة</div>'}</div>`}
window.archiveItem=(target,id,archived)=>openModal(archived?'تأكيد الأرشفة':'تأكيد الاسترجاع',formwrap([`<div class="full info warn">لن يتم حذف البيانات. يسجل النظام الحساب والتوقيت. يجب إعادة إدخال كلمة مرور الإدارة للتأكيد.</div>`,field('password','كلمة مرور الإدارة','password','','required')],archived?'تأكيد الأرشفة':'تأكيد الاسترجاع'),v=>api('/archive',{target,id,archived,confirm:true,password:v.password}));
async function auditPage(){const rows=await api('/audit');$('#main').innerHTML=`<div class="panel"><h3>سجل العمليات (آخر 200 عملية)</h3><div class="table-wrap"><table><tr><th>التاريخ والوقت</th><th>الحساب</th><th>العملية</th><th>الكيان</th><th>الرقم</th><th>التفاصيل</th></tr>${rows.map(x=>`<tr><td>${esc(dateDisplay(x.timestamp))}</td><td>${esc(x.actor_name||x.username)} · ${esc(x.username)} · ${esc(roleLabels[x.actor_role]||'غير متاح بالسجل القديم')}</td><td>${esc(actionLabel(x.action))}</td><td>${esc(entityLabels[x.entity]||x.entity)} · ${esc(x.subject_name)} ${esc(x.employee_no)}</td><td>${esc(x.entity_id)}</td><td class="preserve-lines">${esc(auditDetails(x))}</td></tr>`).join('')}</table></div></div>`}
const roleLabels={admin:'أدمن',manager:'مشرف',employee:'موظف'};
const entityLabels={database:'قاعدة البيانات',user:'حساب',employee:'موظف',company:'شركة',request:'طلب',attendance:'حضور وانصراف',schedules:'جدول عمل',work_sites:'موقع عمل',holidays:'عطلة رسمية'};
function actionLabel(action){return ({assistant_answer:'إجابة مساعد إحكام AI',supervisor_account_create:'إنشاء حساب مشرف',employee_company_move:'نقل موظف بين الشركات',business_data_reset:'مسح بيانات الشركات والموظفين',create:'إنشاء',update:'تعديل بيانات',view:'عرض',login:'تسجيل دخول',logout:'تسجيل خروج',notifications_read:'تعليم الإشعارات كمقروءة',password_reset:'إعادة تعيين كلمة المرور',archive:'أرشفة',restore:'استرجاع',comment:'إضافة ملاحظة',check_in:'تسجيل حضور',check_out:'تسجيل انصراف',policy_update:'تعديل السياسة',contract_renewal:'تجديد العقد',employee_file_upload:'رفع مستند موظف',leave_settlement:'تسوية رصيد الإجازة',absence_approved:'اعتماد خصم الغياب',absence_excused:'اعتماد عذر الغياب',absence_reversed_by_correction:'عكس خصم الغياب بعد تصحيح البصمة',overtime_approved:'اعتماد وقت إضافي',overtime_rejected:'رفض وقت إضافي'})[action]||(action.startsWith('status_')?'تغيير حالة الطلب: '+(statuses[action.slice(7)]||action.slice(7)):action)}
function auditDetails(x){let info=x.info;try{const d=JSON.parse(info);if(d.audit_version===1)info=d.details}catch{}try{if(typeof info==='string')info=JSON.parse(info)}catch{}const labels={deleted_counts:'أعداد السجلات المحذوفة',backup_file:'ملف النسخة الاحتياطية',...reportLabels,...additionalEmployeeFields,amount:'مبلغ السلفة',installment:'القسط الشهري',photo:'الصورة الشخصية',name:'الاسم',name_en:'الاسم بالإنجليزية',identity_no:'الهوية / الإقامة',manager_id:'المشرف المباشر',contract_start:'بداية العقد',contract_end:'نهاية العقد',phone_country:'مفتاح الدولة',phone_local:'الجوال',email:'البريد الإلكتروني',site_id:'موقع العمل',schedule_id:'جدول العمل',salary_basis:'أساس أجر اليوم',notice_days:'فترة الإشعار',advance_min_days:'حد الأيام المتبقية للسلفة',approval_mode:'مسار الاعتماد',geofence_radius:'النطاق بالمتر',city:'المدينة',address:'العنوان'};if(info&&typeof info==='object')info=Object.entries(info).map(([k,v])=>`${labels[k]||k}: ${v&&typeof v==='object'&&'before' in v?`قبل: ${v.before??'—'}، بعد: ${v.after??'—'}`:typeof v==='object'?JSON.stringify(v):v}`).join('\n');return [x.request_type?types[x.request_type]||x.request_type:'',info].filter(Boolean).join(' · ')}
function syncRecoveryVisibility(){$('#forgotPassword').hidden=document.querySelector('[name=account_role]:checked')?.value!=='employee'}
document.querySelectorAll('[name=account_role]').forEach(x=>x.addEventListener('change',syncRecoveryVisibility));
$('#loginForm').addEventListener('reset',()=>setTimeout(syncRecoveryVisibility,0));syncRecoveryVisibility();
window.addEventListener('DOMContentLoaded',()=>login(),{once:true});

